// === Tab: sketch.js ===
/*
Particle sandbox

Controls:
	- Move the mouse around the interact with the particles.
	- Mouse click to reset the scene.
	- Hold middle mouse click to attract.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

var bobCount = 3000;
var bobs = [];
var globalHue;


function setup() {
	createCanvas(1024, 768);
	colorMode(HSB, 255);
	reset();
}


function draw() {
	background(10);
	for (let i = 0; i < bobs.length; i++) {
		let b = bobs[i];
		b.move();

		stroke(b.hue, b.bright, 255);

		// Exaggerate vector from lastPos to pos.
		let newPos = b.pos.copy();
		newPos.sub(b.lastPos);
		newPos.mult(15);
		newPos.add(b.pos);

		line(newPos.x, newPos.y, b.pos.x, b.pos.y);
	}
}


function mouseClicked() {
	reset();
}


function reset() {
	globalHue = random(255);

	bobs.splice(0, bobs.length);

	for (let i = 0; i < bobCount; i++) {
		bobs.push(new Bob(random(width), random(height)));
	}

	// Make sure mouse doesn't immediately effect particles.
	window.simulatedMouseX = -9999;
	window.simulatedMouseY = -9999;

	background(10);
}

// === Tab: bob.js ===
function Bob(x, y) {

	this.lastPos = new p5.Vector(x, y);
  this.pos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
	this.vel.mult(random(0.1));
  this.acc = new p5.Vector(0, 0);
  this.drag = random(0.98, 0.99);
	this.hue = (globalHue + random(-40, 40)) % 255;
	this.bright = random(255);

  this.move = function() {
		this.lastPos.x = this.pos.x;
		this.lastPos.y = this.pos.y;

		// Add some air drag so it can eventually settle.
		this.vel.mult(this.drag);

    // Push it away from the mouse.
    let mouseDist = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let mouseThresh = 300;

		let mult = 0.001;
		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == CENTER) {
			mult *= -1;
		}

    if (mouseDist < mouseThresh) {
      let push = new p5.Vector(this.pos.x, this.pos.y);
      push.sub(new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      push.normalize();
      push.mult((mouseThresh - mouseDist) * mult);
      this.acc.add(push);
    }

		// Move it.
		this.vel.add(this.acc);
		this.vel.limit(6);
		this.pos.add(this.vel);
		this.acc.mult(0);

		// Keep in bounds.
		if (this.pos.x < 0) {
			this.pos.x = width;
			this.lastPos.x = width;
		} else if (this.pos.x > width) {
			this.pos.x = 0;
			this.lastPos.x = 0;
		}

		if (this.pos.y < 0) {
			this.pos.y = height;
			this.lastPos.y = height;
		} else if (this.pos.y > height) {
			this.pos.y = 0;
			this.lastPos.y = 0;
		}
	}

}

